// Financial domain rules shared by finance, payments, reports and dashboards.
//
// Invariants kept by this module:
//  1. A charge's paid amount is DERIVED from allocations of payments whose
//     status is 'recorded' — it is never stored, so it cannot drift.
//  2. The sum of charges generated by a call for funds equals the call total
//     (rounding remainder is assigned to the last lot).
//  3. Confirmed payments are never deleted: they are reversed, with a reason.
//  4. A payment can never be allocated beyond what a lot still owes.
import { db } from './store.js';
import { todayIso, sum } from './dom.js';

export const round2 = (n) => Math.round((Number(n) + Number.EPSILON) * 100) / 100;
const EPS = 0.004;

/** Map chargeId -> amount paid, from recorded payments only. */
export function paidMap() {
  const map = new Map();
  for (const p of db.all('payments')) {
    if (p.status !== 'recorded') continue;
    for (const a of p.allocations || []) map.set(a.chargeId, (map.get(a.chargeId) || 0) + a.amount);
  }
  return map;
}

/** Charge enriched with paid / due / status. */
export function chargeView(charge, map = paidMap()) {
  const paid = round2(map.get(charge.id) || 0);
  const due = Math.max(0, round2(charge.amount - paid));
  const overdue = due > EPS && charge.dueDate < todayIso();
  let status = 'unpaid';
  if (due <= EPS) status = 'paid';
  else if (paid > EPS) status = 'partial';
  else if (overdue) status = 'overdue';
  return { ...charge, paid, due, status, overdue };
}

export function chargeViews(charges, map = paidMap()) {
  return charges.map((c) => chargeView(c, map));
}

/** Charges of a lot that still have an outstanding amount, oldest first. */
export function openCharges(unitId, map = paidMap()) {
  return db
    .all('charges')
    .filter((c) => c.unitId === unitId)
    .map((c) => chargeView(c, map))
    .filter((c) => c.due > EPS)
    .sort((a, b) => a.dueDate.localeCompare(b.dueDate));
}

export const unitBalance = (unitId, map = paidMap()) => round2(sum(openCharges(unitId, map), (c) => c.due));

/** FIFO allocation of an amount on the oldest outstanding charges of a lot. */
export function allocate(unitId, value) {
  let left = round2(value);
  const allocations = [];
  for (const c of openCharges(unitId)) {
    if (left <= EPS) break;
    const part = round2(Math.min(left, c.due));
    allocations.push({ chargeId: c.id, amount: part });
    left = round2(left - part);
  }
  return { allocations, unallocated: left };
}

/** Preview of the per-lot amounts a call for funds will generate. */
export function distribute(call) {
  const units = db.all('units').filter((u) => u.residenceId === call.residenceId);
  if (!units.length) return [];
  if (call.basis === 'fixed') return units.map((u) => ({ unit: u, amount: round2(call.amountPerUnit) }));
  const totalShares = sum(units, (u) => u.tantiemes);
  if (!totalShares) return [];
  let assigned = 0;
  return units.map((u, i) => {
    const isLast = i === units.length - 1;
    const share = isLast ? round2(call.totalAmount - assigned) : round2((call.totalAmount * u.tantiemes) / totalShares);
    assigned = round2(assigned + share);
    return { unit: u, amount: share };
  });
}

/** Issue a draft call: generate one charge per lot. Returns number of charges. */
export function issueCall(call) {
  const lines = distribute(call);
  for (const line of lines) {
    db.insert(
      'charges',
      {
        callId: call.id,
        residenceId: call.residenceId,
        unitId: line.unit.id,
        label: call.title,
        amount: line.amount,
        dueDate: call.dueDate,
      },
      { silent: true },
    );
  }
  db.update('calls', call.id, { status: 'issued', issuedAt: new Date().toISOString() }, { action: 'issue' });
  return lines.length;
}

export function callStats(call, map = paidMap()) {
  const charges = chargeViews(db.all('charges').filter((c) => c.callId === call.id), map);
  const total = call.status === 'draft' ? round2(sum(distribute(call), (l) => l.amount)) : round2(sum(charges, (c) => c.amount));
  const paid = round2(sum(charges, (c) => c.paid));
  return { total, paid, due: round2(total - paid), rate: total ? paid / total : 0, count: charges.length };
}

/** Chronological account statement of a lot, with running balance. */
export function statement(unitId) {
  const lines = [];
  for (const c of db.all('charges').filter((x) => x.unitId === unitId)) {
    lines.push({ date: c.dueDate, kind: 'charge', label: c.label, debit: c.amount, credit: 0, ref: '' });
  }
  for (const p of db.all('payments').filter((x) => x.unitId === unitId && x.status === 'recorded')) {
    lines.push({ date: p.date, kind: 'payment', label: p.method, debit: 0, credit: p.amount, ref: p.receiptNo || '' });
  }
  lines.sort((a, b) => a.date.localeCompare(b.date) || (a.kind === 'charge' ? -1 : 1));
  let balance = 0;
  for (const l of lines) {
    balance = round2(balance + l.debit - l.credit);
    l.balance = balance;
  }
  return lines;
}

/** Aggregated figures for a set of residences. */
export function summary(residenceIds) {
  const ids = new Set(residenceIds);
  const map = paidMap();
  const charges = chargeViews(db.all('charges').filter((c) => ids.has(c.residenceId)), map);
  const charged = round2(sum(charges, (c) => c.amount));
  const collected = round2(sum(charges, (c) => c.paid));
  const overdue = round2(sum(charges.filter((c) => c.overdue), (c) => c.due));
  const expenses = round2(
    sum(db.all('expenses').filter((e) => ids.has(e.residenceId) && e.status === 'paid'), (e) => e.amount),
  );
  return {
    charges,
    charged,
    collected,
    outstanding: round2(charged - collected),
    overdue,
    expenses,
    rate: charged ? collected / charged : 0,
    balance: round2(collected - expenses),
  };
}

/** Recorded payments / paid expenses per month for the last `count` months. */
export function monthlySeries(residenceIds, count = 6) {
  const ids = new Set(residenceIds);
  const now = new Date();
  const months = [];
  for (let i = count - 1; i >= 0; i--) {
    const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    months.push({ year: d.getFullYear(), month: d.getMonth(), key: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`, collected: 0, spent: 0 });
  }
  const byKey = new Map(months.map((m) => [m.key, m]));
  for (const p of db.all('payments')) {
    if (p.status !== 'recorded' || !ids.has(p.residenceId)) continue;
    const m = byKey.get(p.date.slice(0, 7));
    if (m) m.collected = round2(m.collected + p.amount);
  }
  for (const e of db.all('expenses')) {
    if (e.status !== 'paid' || !ids.has(e.residenceId)) continue;
    const m = byKey.get(e.date.slice(0, 7));
    if (m) m.spent = round2(m.spent + e.amount);
  }
  return months;
}
